steps:
STEP 2 — Append seven G6PD-deficient 'avoid' rules to data/rules/pgx.json. All rules share these common fields: module='pgx', version='2.0.0', status='verified', evidenceLevel=null, blocking=true, onUnmetContext='conditional', requires={}, strength='strong'. Gene/phenotype: condition={type:'pgx', gene:'G6PD', phenotypeIn:['deficient']}. Common mechanism: 'G6PD deficiency impairs the hexose monophosphate shunt in red blood cells, reducing NADPH production and leaving erythrocytes unable to defend against oxidative stress; high-risk drugs generate oxidant stress, causing acute haemolytic anaemia.'

  R-PGX-DAPSONE-G6PD-DEFICIENT: drug='dapsone', action='avoid', headline='Dapsone is not recommended in G6PD-deficient patients', rationale='CPIC recommends that high-risk drugs — including dapsone — should be avoided in G6PD-deficient patients (with or without chronic non-spherocytic haemolytic anaemia) due to the risk of acute haemolytic anaemia.', evidence=['E-CPIC-G6PD-2023','G:PA166119846'], alternatives={supported:false, text:'No specific alternative is encoded; see the cited guideline.'}

  R-PGX-METHYLENE-BLUE-G6PD-DEFICIENT: drug='methylene-blue', action='avoid', headline='Methylene blue is not recommended in G6PD-deficient patients', rationale='CPIC recommends avoiding methylene blue in G6PD-deficient patients due to the risk of acute haemolytic anaemia.', evidence=['E-CPIC-G6PD-2023','G:PA166119846'], alternatives={supported:false}

  R-PGX-PEGLOTICASE-G6PD-DEFICIENT: drug='pegloticase', action='avoid', headline='Pegloticase is not recommended in G6PD-deficient patients', rationale='CPIC recommends avoiding pegloticase in G6PD-deficient patients due to risk of acute haemolytic anaemia.', evidence=['E-CPIC-G6PD-2023','G:PA166119846'], alternatives={supported:false}

  R-PGX-RASBURICASE-G6PD-DEFICIENT: drug='rasburicase', action='avoid', headline='Rasburicase is contraindicated in G6PD-deficient patients', rationale='CPIC recommends that rasburicase — a high-risk drug — should be avoided in G6PD-deficient patients; the FDA labelling also contraindicate rasburicase in G6PD deficiency due to risk of acute haemolytic anaemia and methemoglobinaemia.', evidence=['E-CPIC-G6PD-2023','G:PA166119846'], alternatives={supported:false}

  R-PGX-TAFENOQUINE-G6PD-DEFICIENT: drug='tafenoquine', action='avoid', headline='Tafenoquine is not recommended in G6PD-deficient patients', rationale='CPIC recommends avoiding tafenoquine in G6PD-deficient patients due to the risk of acute haemolytic anaemia; tafenoquine is a high-risk 8-aminoquinoline drug in G6PD deficiency.', evidence=['E-CPIC-G6PD-2023','G:PA166119846'], alternatives={supported:false}

  R-PGX-TOLUIDINE-BLUE-G6PD-DEFICIENT: drug='toluidine-blue', action='avoid', headline='Toluidine blue is not recommended in G6PD-deficient patients', rationale='CPIC recommends avoiding toluidine blue (tolonium chloride) in G6PD-deficient patients due to risk of acute haemolytic anaemia.', evidence=['E-CPIC-G6PD-2023','G:PA166119846'], alternatives={supported:false}

  R-PGX-PRIMAQUINE-G6PD-DEFICIENT: drug='primaquine', action='avoid', headline='Primaquine is not recommended in G6PD-deficient patients', rationale='CPIC recommends that primaquine should be avoided in G6PD-deficient patients (with or without chronic non-spherocytic haemolytic anaemia). G:PA166279621 is the primaquine-specific CPIC guideline; G:PA166119846 includes primaquine under the broader G6PD high-risk drug list.', evidence=['E-CPIC-G6PD-2023','G:PA166279621','G:PA166119846'], alternatives={supported:false}
